import { drawingContentKey } from '@frade/draw/document'
/** Both editors export navigation dimensions; navigation/formatting is not a semantic edit. */
export function sameDiagramContent(path: string, left: string, right: string): boolean {
  if (left === right) return true
  if (path.toLowerCase().endsWith('.frade')) {
    try {
      return drawingContentKey(left) === drawingContentKey(right)
    } catch {
      return false
    } // Invalid drawings are never equivalent to different input bytes.
  }
  const parse = (xml: string) => {
    const doc = new DOMParser().parseFromString(xml, 'text/xml')
    if (doc.querySelector('parsererror')) return
    for (const model of doc.querySelectorAll('mxGraphModel')) {
      model.removeAttribute('dx')
      model.removeAttribute('dy')
    }
    return doc.documentElement
  }
  const a = parse(left),
    b = parse(right)
  return !!a && !!b && a.isEqualNode(b)
}

import { parseDocument, type DiagramDocument } from './schema'

export type DrawingPage = {
  id: string
  name: string
  graph: DiagramDocument['graph']
  viewport?: DiagramDocument['viewport']
}
export type MultipageDocument = {
  format: 'frade-draw'
  version: 2
  metadata: DiagramDocument['metadata']
  pages: DrawingPage[]
}
export type DrawingDocument = DiagramDocument | MultipageDocument
export type DrawingState = {
  version: 1 | 2
  metadata: DiagramDocument['metadata']
  pages: DrawingPage[]
  activeId: string
}

function record(value: unknown): Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value))
    throw Error('Invalid drawing structure')
  return value as Record<string, unknown>
}
function name(value: unknown, message: string): string {
  if (typeof value !== 'string' || !value.trim()) throw Error(message)
  return value
}

/** Validate every graph before any editor/session replacement. The v1 API stays unchanged. */
export function parseDrawingDocument(value: unknown): DrawingDocument {
  const input = record(value)
  if (input.version !== 2) return parseDocument(value)
  if (input.format !== 'frade-draw') throw Error('Unsupported document format')
  const metadata = parseDocument({
    format: 'frade-draw',
    version: 1,
    metadata: input.metadata,
    graph: { nodes: [], edges: [] },
  }).metadata
  if (!Array.isArray(input.pages) || !input.pages.length) throw Error('Drawing needs a page')
  const ids = new Set<string>()
  const pages = input.pages.map((value) => {
    const page = record(value),
      id = name(page.id, 'Invalid page ID')
    if (ids.has(id)) throw Error('Duplicate page ID')
    ids.add(id)
    const parsed = parseDocument({
      format: 'frade-draw',
      version: 1,
      metadata,
      graph: page.graph,
      ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
    })
    return {
      id,
      name: name(page.name, 'Invalid page name'),
      graph: parsed.graph,
      ...(parsed.viewport === undefined ? {} : { viewport: parsed.viewport }),
    }
  })
  return { format: 'frade-draw', version: 2, metadata, pages }
}
export const serializeDrawingDocument = (value: DrawingDocument) =>
  JSON.stringify(parseDrawingDocument(value), null, 2)
export const deserializeDrawingDocument = (json: string) => parseDrawingDocument(JSON.parse(json))

export function pageState(value: unknown, firstName = 'Страница-1'): DrawingState {
  const document = parseDrawingDocument(value)
  const pages =
    document.version === 2
      ? document.pages
      : [
          {
            id: document.metadata.id + '/page-1',
            name: firstName,
            graph: document.graph,
            ...(document.viewport === undefined ? {} : { viewport: document.viewport }),
          },
        ]
  return {
    version: document.version,
    metadata: document.metadata,
    pages,
    activeId: pages[0].id,
  }
}
export function drawingDocument(state: DrawingState): DrawingDocument {
  if (state.version === 2)
    return {
      format: 'frade-draw',
      version: 2,
      metadata: state.metadata,
      pages: state.pages,
    }
  const page = state.pages[0]
  return {
    format: 'frade-draw',
    version: 1,
    metadata: state.metadata,
    graph: page.graph,
    ...(page.viewport === undefined ? {} : { viewport: page.viewport }),
  }
}
export function semanticDrawing(value: DrawingDocument) {
  const parsed = parseDrawingDocument(value)
  if (parsed.version === 1) {
    return {
      format: parsed.format,
      version: parsed.version,
      metadata: parsed.metadata,
      graph: parsed.graph,
    }
  }
  return {
    ...parsed,
    pages: parsed.pages.map(({ id, name, graph }) => ({ id, name, graph })),
  }
}
/** Semantic dirty key: object formatting/order and navigation are not diagram edits. */
export function drawingContentKey(json: string): string {
  return JSON.stringify(semanticDrawing(deserializeDrawingDocument(json)), (_key, value) =>
    value && typeof value === 'object' && !Array.isArray(value)
      ? Object.fromEntries(
          Object.keys(value)
            .sort()
            .map((key) => [key, value[key]]),
        )
      : value,
  )
}
function pageIndex(state: DrawingState, id: string) {
  const index = state.pages.findIndex((page) => page.id === id)
  if (index < 0) throw Error('Page no longer exists')
  return index
}
function newPage(state: DrawingState, page: DrawingPage) {
  if (state.pages.some((current) => current.id === page.id)) throw Error('Duplicate page ID')
  const parsed = parseDrawingDocument({
    format: 'frade-draw',
    version: 2,
    metadata: state.metadata,
    pages: [page],
  }) as MultipageDocument
  return parsed.pages[0]
}
export function nextPageName(pages: DrawingPage[], numbered: (index: number) => string) {
  const names = new Set(pages.map((page) => page.name))
  let index = pages.length + 1
  while (names.has(numbered(index))) index++
  return numbered(index)
}
export function insertDrawingPage(state: DrawingState, value: DrawingPage): DrawingState {
  const page = newPage(state, value)
  return {
    ...state,
    version: 2,
    pages: [...state.pages, page],
    activeId: page.id,
  }
}
export function duplicateDrawingPage(
  state: DrawingState,
  sourceId: string,
  id: string,
  copyName: string,
): DrawingState {
  const index = pageIndex(state, sourceId),
    source = state.pages[index]
  const graph = structuredClone(source.graph)
  const mapped = new Map(graph.nodes.map((node) => [node.id, id + '/' + node.id]))
  for (const node of graph.nodes) node.id = mapped.get(node.id)!
  for (const edge of graph.edges) {
    edge.id = id + '/' + edge.id
    edge.source.nodeId = mapped.get(edge.source.nodeId)!
    edge.target.nodeId = mapped.get(edge.target.nodeId)!
  }
  const page = newPage(state, { id, name: copyName, graph })
  const pages = state.pages.slice()
  pages.splice(index + 1, 0, page)
  return { ...state, version: 2, pages, activeId: id }
}
export function renameDrawingPage(state: DrawingState, id: string, value: string): DrawingState {
  const index = pageIndex(state, id)
  if (!value.trim() || state.pages[index].name === value) return state
  return {
    ...state,
    version: 2,
    pages: state.pages.map((page, i) => (i === index ? { ...page, name: value } : page)),
  }
}
export function clearDrawingPages(state: DrawingState, replacement: DrawingPage): DrawingState {
  const page = newPage(state, replacement)
  return { ...state, version: 2, pages: [page], activeId: page.id }
}
export function removeDrawingPage(
  state: DrawingState,
  id: string,
  replacement: DrawingPage,
): DrawingState {
  const index = pageIndex(state, id)
  if (state.pages.length === 1) return clearDrawingPages(state, replacement)
  const pages = state.pages.filter((page) => page.id !== id)
  return {
    ...state,
    version: 2,
    pages,
    activeId: state.activeId === id ? pages[Math.min(index, pages.length - 1)].id : state.activeId,
  }
}
export function moveDrawingPage(
  state: DrawingState,
  id: string,
  destination: number,
): DrawingState {
  const index = pageIndex(state, id)
  if (!Number.isInteger(destination) || destination < 0 || destination >= state.pages.length)
    throw Error('Invalid page position')
  if (index === destination) return state
  const pages = state.pages.slice(),
    page = pages.splice(index, 1)[0]
  pages.splice(destination, 0, page)
  return { ...state, version: 2, pages }
}
export function sortDrawingPages(state: DrawingState, locale: string): DrawingState {
  const compare = new Intl.Collator(locale, {
    numeric: true,
    sensitivity: 'base',
  })
  const pages = state.pages.slice().sort((a, b) => compare.compare(a.name, b.name))
  return pages.every((page, i) => page === state.pages[i]) ? state : { ...state, version: 2, pages }
}

import {
  deserializeDrawingDocument,
  serializeDrawingDocument,
  type DrawingDocument,
} from '../document/drawing'
const prefix = 'frade.page-transfer/',
  fragment = '#frade-page='
const lifetime = 60000
/** One-shot same-origin application transfer; never a write-back document reference. */
export function receivePageTransfer(): DrawingDocument | undefined {
  if (!location.hash.startsWith(fragment)) return
  const key = prefix + decodeURIComponent(location.hash.slice(fragment.length))
  const raw = localStorage.getItem(key)
  localStorage.removeItem(key)
  history.replaceState(null, '', location.pathname + location.search)
  if (!raw) throw Error('Не удалось открыть копию страницы')
  const value = JSON.parse(raw)
  if (
    typeof value.created !== 'number' ||
    Date.now() - value.created > lifetime ||
    typeof value.document !== 'string'
  )
    throw Error('Истекло время открытия копии страницы')
  return deserializeDrawingDocument(value.document)
}
export function openTransferredPage(document: DrawingDocument) {
  const id = crypto.randomUUID(),
    key = prefix + id
  localStorage.setItem(
    key,
    JSON.stringify({
      created: Date.now(),
      document: serializeDrawingDocument(document),
    }),
  )
  const child = window.open('about:blank', '_blank')
  if (!child) {
    localStorage.removeItem(key)
    throw Error('Разрешите открытие нового окна для страницы')
  }
  child.opener = null
  const url = new URL(location.href)
  url.hash = fragment.slice(1) + encodeURIComponent(id)
  try {
    child.location.href = url.toString()
  } catch (error) {
    localStorage.removeItem(key)
    child.close()
    throw error
  }
  setTimeout(() => localStorage.removeItem(key), lifetime)
}

import { useEffect, useLayoutEffect, useRef, useState, useId } from 'react'
import type { Graph } from '@antv/x6'
import { createGraph } from './createGraph'
import { nodeToCell } from '../document/graphAdapter'
import { downloadDocument, readDocument } from '../document/fileAdapter'
import { diagramShapes, type DiagramDocument, type DiagramShape } from '../document/schema'
import { installSegmentAdapter } from '../segment-editing/x6Adapter'
import { createDrawingSession, type DrawingSession } from './drawingSession'
import { PageStrip } from './PageStrip'
import type { PageOverlayHost } from './PageStrip'
import { receivePageTransfer, openTransferredPage } from './pageTransfer'
import { pageLabels } from './generated/drawio-pages'

export type DiagramEditorProps = {
  embedded?: boolean
  onGraphReady?: (graph: Graph, session: DrawingSession) => void | (() => void)
  requestDocumentName?: (currentName: string) => string | null | Promise<string | null>
  initialDocument?: unknown
  readOnly?: boolean
  locale?: keyof typeof pageLabels
  pageOverlays?: PageOverlayHost
}
const newMetadata = () => ({ id: crypto.randomUUID(), name: 'diagram' })
let number = 1
export function DiagramEditor({
  onGraphReady,
  requestDocumentName,
  embedded,
  initialDocument,
  readOnly = false,
  locale = 'ru',
  pageOverlays,
}: DiagramEditorProps) {
  const host = useRef<HTMLDivElement>(null)
  const graph = useRef<Graph | null>(null)
  const setup = useRef({ locale, readOnly })
  useLayoutEffect(() => {
    setup.current = { locale, readOnly }
  }, [locale, readOnly])
  const initial = useRef(initialDocument),
    controller = useRef<DrawingSession>()
  const [session, setSession] = useState<DrawingSession>()
  const [, refresh] = useState(0)
  const idPrefix = 'frade-drawing-' + useId().replaceAll(':', '')
  const readGeneration = useRef(0)
  const [selected, setSelected] = useState<string | null>(null)
  const [gridVisible, setGridVisible] = useState(true)
  const [error, setError] = useState('')
  const [opening, setOpening] = useState(false)
  const fileInput = useRef<HTMLInputElement>(null)
  useEffect(() => {
    const generationRef = readGeneration
    if (!host.current) return
    const instance = createGraph(host.current)
    graph.current = instance
    const empty: DiagramDocument = {
      format: 'frade-draw',
      version: 1,
      metadata: newMetadata(),
      graph: { nodes: [], edges: [] },
    }
    let model = initial.current
    if (model === undefined)
      try {
        model = receivePageTransfer()
      } catch (error) {
        setError(error instanceof Error ? error.message : String(error))
      }
    let drawing: DrawingSession
    try {
      drawing = createDrawingSession(instance, model ?? empty, {
        firstPageName: pageLabels[setup.current.locale].pageWithNumber.replace('{1}', '1'),
        onError: (error) => setError(error.message),
      })
    } catch (error) {
      setError(error instanceof Error ? error.message : String(error))
      drawing = createDrawingSession(instance, empty)
    }
    drawing.setReadOnly(setup.current.readOnly)
    controller.current = drawing
    const unsubscribe = drawing.subscribe(() => refresh((value) => value + 1))
    setSession(drawing)
    const resize = () => instance.resize?.(host.current!.clientWidth, host.current!.clientHeight)
    resize()
    const observer = typeof ResizeObserver === 'undefined' ? undefined : new ResizeObserver(resize)
    observer?.observe(host.current)
    const disposeHostIntegration = onGraphReady?.(instance, drawing)
    instance.on('selection:changed', ({ selected }) => {
      instance.getEdges().forEach((edge) => edge.removeTools())
      const cell = selected[0]
      if (cell?.isEdge()) installSegmentAdapter(cell)
      setSelected(cell?.id ?? null)
    })
    return () => {
      generationRef.current++
      observer?.disconnect()
      disposeHostIntegration?.()
      unsubscribe()
      drawing.dispose()
      instance.dispose()
      graph.current = null
      controller.current = undefined
    }
  }, [onGraphReady])
  useLayoutEffect(() => {
    const instance = graph.current
    if (!instance || !session) return
    session.setReadOnly(readOnly || opening)
    const previous = instance.options.interacting
    if (readOnly || opening) {
      instance.options.interacting = false
      instance.disableKeyboard()
      instance.cleanSelection()
      instance.clearTransformWidgets()
    } else instance.enableKeyboard()
    return () => {
      instance.options.interacting = previous
    }
  }, [readOnly, opening, session])
  const add = (shape: DiagramShape) => {
    const instance = graph.current
    if (!instance || readOnly || opening) return
    let id: string
    do {
      id = 'node-' + number++
    } while (instance.getCellById(id))
    instance.addNode(
      nodeToCell({
        id,
        shape,
        x: 120 + number * 12,
        y: 120 + number * 12,
        width: 150,
        height: 72,
        label: shape === 'text' ? 'Text' : 'New shape',
      }),
    )
  }
  const remove = () => {
    if (selected && !readOnly && !opening) graph.current?.removeCell(selected)
  }
  const zoom = (amount: number) => graph.current?.zoom(amount)
  const toggleGrid = () => {
    const next = !gridVisible
    setGridVisible(next)
    if (next) graph.current?.showGrid()
    else graph.current?.hideGrid()
  }
  const save = async (saveAs = false) => {
    const instance = graph.current,
      drawing = controller.current
    if (!instance || !drawing || readOnly) return
    const generation = readGeneration.current
    try {
      const next = drawing.snapshot().metadata
      if (saveAs) {
        const name = requestDocumentName
          ? await requestDocumentName(next.name)
          : window.prompt('Document name', next.name)
        if (generation !== readGeneration.current || graph.current !== instance) return
        if (name === null) return
        if (!name.trim()) {
          setError('Document name must not be empty.')
          return
        }
        drawing.setName(name.trim())
      }
      downloadDocument(drawing.snapshot())
      setError('')
    } catch (error) {
      setError(error instanceof Error ? error.message : 'Could not save the document.')
    }
  }
  const createNew = () => {
    const instance = graph.current
    if (!instance || readOnly) return
    readGeneration.current++
    setOpening(false)
    const next = newMetadata()
    controller.current?.load({
      format: 'frade-draw',
      version: 1,
      metadata: next,
      graph: { nodes: [], edges: [] },
    })
    setSelected(null)
    setError('')
  }
  const open = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0],
      instance = graph.current
    event.target.value = ''
    if (!file || !instance) return
    const generation = ++readGeneration.current
    setOpening(true)
    try {
      const model = await readDocument(file)
      if (generation !== readGeneration.current || graph.current !== instance) return
      controller.current?.load(model)
      setSelected(null)
      setError('')
    } catch (error) {
      if (generation === readGeneration.current)
        setError(error instanceof Error ? error.message : 'Could not open the document.')
    } finally {
      if (generation === readGeneration.current) setOpening(false)
    }
  }
  return (
    <main className="frade-drawing-editor">
      <header>
        <strong>Frade Draw</strong>
        {!embedded && (
          <>
            <button onClick={createNew} disabled={readOnly}>
              New
            </button>
            <button onClick={() => save()} disabled={opening || readOnly}>
              Save
            </button>
            <button onClick={() => save(true)} disabled={opening || readOnly}>
              Save As
            </button>
            <button onClick={() => fileInput.current?.click()}>Open</button>
            <input
              ref={fileInput}
              type="file"
              accept="application/json,.json"
              aria-label="Open diagram"
              hidden
              onChange={open}
            />
          </>
        )}
        <button onClick={remove} disabled={!selected || opening || readOnly}>
          Delete
        </button>
        <button
          onClick={() => graph.current?.undo()}
          disabled={opening || readOnly}
        >
          Undo
        </button>
        <button
          onClick={() => graph.current?.redo()}
          disabled={opening || readOnly}
        >
          Redo
        </button>
        <button onClick={() => zoom(0.1)}>Zoom +</button>
        <button onClick={() => zoom(-0.1)}>Zoom −</button>
        <button onClick={() => graph.current?.zoomToFit({ padding: 30 })}>Fit</button>
        <button onClick={toggleGrid}>Grid</button>
        <button onClick={() => graph.current?.exportSVG('diagram.svg')}>SVG</button>
        <button onClick={() => graph.current?.exportPNG('diagram.png')}>PNG</button>
      </header>
      <aside>
        {diagramShapes.map((shape) => (
          <button key={shape} disabled={opening || readOnly} onClick={() => add(shape)}>
            {shape}
          </button>
        ))}
        {error && <p role="alert">{error}</p>}
      </aside>
      <div
        className="canvas"
        ref={host}
        id={idPrefix + '-canvas'}
        role="tabpanel"
        aria-labelledby={
          session ? idPrefix + '-page-' + encodeURIComponent(session.view().activeId) : undefined
        }
        style={opening ? { pointerEvents: 'none' } : undefined}
      />
      {session && (
        <PageStrip
          overlays={pageOverlays}
          session={session}
          locale={locale}
          idPrefix={idPrefix}
          embedded={embedded}
          onError={setError}
          onOpenPage={(id) => {
            openTransferredPage(session.extract(id, crypto.randomUUID()))
          }}
        />
      )}
    </main>
  )
}

import { createHash, randomUUID } from 'node:crypto'
import {
  lstat,
  mkdir,
  open,
  readFile,
  readdir,
  rename,
  unlink,
  realpath,
  link,
} from 'node:fs/promises'
import { join } from 'node:path'
import { inflateRawSync } from 'node:zlib'
import { deserializeDrawingDocument } from '@frade/draw/document'
import { SaxesParser } from 'saxes'
import {
  failure,
  success,
  type JsonValue,
  type Result,
  type ErrorCode,
} from '@frade/repository-domain'

export const EMPTY_DIAGRAM =
  '<mxfile host="Frade"><diagram id="page-1" name="Page-1"><mxGraphModel><root><mxCell id="0"/><mxCell id="1" parent="0"/></root></mxGraphModel></diagram></mxfile>'
const limit = 4 * 1024 * 1024
const hash = (text: string) => createHash('sha256').update(text).digest('hex')
const fail = (code: string): never => {
  throw new Error(code)
}
export function diagramParts(path: string): string[] {
  const parts = path.split('/')
  if (
    parts[0] !== '_diagrams' ||
    parts.length > 32 ||
    parts.some(
      (p) =>
        !p ||
        p === '.' ||
        p === '..' ||
        /[\\:<>"|?*]/.test(p) ||
        [...p].some((c) => c.charCodeAt(0) < 32) ||
        /[. ]$/.test(p) ||
        /^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(p) ||
        p.startsWith('.frade-'),
    )
  )
    fail('INVALID_PATH')
  return parts
}
export function validateDiagram(xml: string, modelOnly = false) {
  if (Buffer.byteLength(xml) > limit || /<!DOCTYPE/i.test(xml)) fail('INVALID_DIAGRAM')
  let root = '',
    depth = 0,
    pages = 0,
    model = 0,
    text = '',
    embedded = false,
    expanded = 0
  const parser = new SaxesParser({ xmlns: false })
  parser.on('opentag', (t) => {
    if (!depth++) root = t.name
    if (depth > 128 || (modelOnly && root !== 'mxGraphModel')) fail('INVALID_DIAGRAM')
    if (t.name === 'diagram') {
      if (++pages > 100) fail('INVALID_DIAGRAM')
      text = ''
      embedded = false
    }
    if (t.name === 'mxGraphModel') {
      model++
      embedded = true
    }
  })
  parser.on('text', (value) => {
    if (depth === 2 && root === 'mxfile') text += value
  })
  parser.on('closetag', (t) => {
    if (t.name === 'diagram' && !embedded) {
      if (!text.trim()) fail('INVALID_DIAGRAM')
      const decoded = decodeURIComponent(
        inflateRawSync(Buffer.from(text.trim(), 'base64'), {
          maxOutputLength: 16 * 1024 * 1024,
        }).toString('utf8'),
      )
      expanded += Buffer.byteLength(decoded)
      if (expanded > 16 * 1024 * 1024) fail('INVALID_DIAGRAM')
      validateDiagram(decoded, true)
    }
    depth--
  })
  try {
    parser.write(xml).close()
  } catch {
    fail('INVALID_DIAGRAM')
  }
  if ((root !== 'mxfile' && root !== 'mxGraphModel') || (root === 'mxfile' ? !pages : !model))
    fail('INVALID_DIAGRAM')
}
export class DiagramFiles {
  private tail: Promise<unknown> = Promise.resolve()
  constructor(
    private root: string,
    private readOnly = false,
  ) {}
  private async path(entry: string, parents = false) {
    const parts = diagramParts(entry)
    let path = await realpath(this.root)
    for (let i = 0; i < parts.length; i++) {
      path = join(path, parts[i])
      try {
        const stat = await lstat(path)
        if (stat.isSymbolicLink() || (i < parts.length - 1 && !stat.isDirectory()))
          fail('INVALID_PATH')
      } catch (e) {
        if ((e as NodeJS.ErrnoException).code !== 'ENOENT') throw e
        if (parents && i < parts.length - 1) await mkdir(path)
      }
    }
    return path
  }
  private async read(entry: string) {
    const path = await this.path(entry),
      stat = await lstat(path)
    if (!stat.isFile() || stat.size > limit) fail('INVALID_DIAGRAM')
    const xml = await readFile(path, 'utf8')
    if (entry.toLowerCase().endsWith('.frade')) deserializeDrawingDocument(xml)
    else validateDiagram(xml)
    return { path: entry, xml, revision: hash(xml) }
  }
  execute(payload: Readonly<Record<string, JsonValue>>): Promise<Result<unknown>> {
    const run = this.tail
      .then(() => this.perform(payload))
      .catch((e) =>
        failure(
          e instanceof Error &&
            [
              'INVALID_PATH',
              'INVALID_DIAGRAM',
              'REVISION_CONFLICT',
              'REPOSITORY_READ_ONLY',
              'LIMIT_EXCEEDED',
            ].includes(e.message)
            ? (e.message as ErrorCode)
            : (e as NodeJS.ErrnoException).code === 'ENOENT'
              ? 'ENTITY_NOT_FOUND'
              : (e as NodeJS.ErrnoException).code === 'EEXIST'
                ? 'ALREADY_EXISTS'
                : 'REPOSITORY_UNAVAILABLE',
        ),
      )
    this.tail = run
    return run
  }
  private async perform(p: Readonly<Record<string, JsonValue>>): Promise<Result<unknown>> {
    const action = String(p.action),
      entry = typeof p.path === 'string' ? p.path : '_diagrams'
    if (action === 'list') {
      const entries: { path: string; kind: 'file' | 'folder' }[] = []
      const visit = async (folder: string) => {
        const path = await this.path(folder)
        let children
        try {
          children = await readdir(path, { withFileTypes: true })
        } catch (e) {
          if ((e as NodeJS.ErrnoException).code === 'ENOENT') return
          throw e
        }
        for (const child of children.sort((a, b) => a.name.localeCompare(b.name))) {
          if (child.isSymbolicLink() || child.name.startsWith('.frade-')) continue
          const path = folder + '/' + child.name
          diagramParts(path)
          if (entries.length >= 2000) fail('LIMIT_EXCEEDED')
          if (child.isDirectory()) {
            entries.push({ path, kind: 'folder' })
            await visit(path)
          } else if (child.isFile()) entries.push({ path, kind: 'file' })
        }
      }
      await visit('_diagrams')
      return success({ entries })
    }
    if (action === 'read') return success(await this.read(entry))
    if (this.readOnly) fail('REPOSITORY_READ_ONLY')
    if (entry === '_diagrams' && action !== 'folder') fail('INVALID_PATH')
    if (action === 'folder') {
      await mkdir(await this.path(entry, true), { recursive: false })
      return success({ path: entry })
    }
    if (action === 'rename') {
      const source = await this.path(entry),
        destination = String(p.destination)
      if (entry.toLowerCase().endsWith('.frade') !== destination.toLowerCase().endsWith('.frade'))
        fail('INVALID_DIAGRAM')
      if (entry === destination) return success({ path: entry })
      const before = await this.read(entry)
      if (p.revision !== before.revision) fail('REVISION_CONFLICT')
      const target = await this.path(destination, true)
      // Hard-link creation is exclusive: renaming never overwrites an existing file.
      await link(source, target)
      try {
        await unlink(source)
      } catch (e) {
        await unlink(target)
        throw e
      }
      return success({ path: destination })
    }
    const xml =
      action === 'create'
        ? typeof p.xml === 'string'
          ? p.xml
          : entry.toLowerCase().endsWith('.frade')
            ? JSON.stringify({
                format: 'frade-draw',
                version: 1,
                metadata: { id: randomUUID(), name: entry.split('/').at(-1) },
                graph: { nodes: [], edges: [] },
              })
            : EMPTY_DIAGRAM
        : String(p.xml)
    if (Buffer.byteLength(xml) > limit) fail('INVALID_DIAGRAM')
    if (entry.toLowerCase().endsWith('.frade')) {
      try {
        deserializeDrawingDocument(xml)
      } catch {
        fail('INVALID_DIAGRAM')
      }
    } else validateDiagram(xml)
    const target = await this.path(entry, true)
    if (action === 'create') {
      const handle = await open(target, 'wx')
      try {
        await handle.writeFile(xml, 'utf8')
        await handle.sync()
      } finally {
        await handle.close()
      }
    } else if (action === 'write') {
